mapper.select:
SELECT EXISTS (
SELECT 1
FROM reviews
WHERE user_id = #{userId}
AND spot_id = #{spotId}
)

mapper.update:
UPDATE reviews SET rating = #{rating},comment =
#{comment}
WHERE user_id = #{userId}
AND spot_id = #{spotId}

mapper.delete:
DELETE FROM reviews
WHERE user_id = #{userId}
AND
spot_id = #{spotId}
